void test_intrinsic_default_pointer_reference_loop(
    v64bfp16ebs8_unaligned *&p, v64bfp16ebs8 v, int num) {
  fifo_state_t s;
  s.pos = 0;
  for (int i = 0; i < num; ++i) {
    fifo_st_push(p, v, s);
    fifo_st_flush(p, s);
  }
}
